// packages/domain/src/totp-utils.ts
function parseTotpSecret(rawSecret) {
  const trimmed = rawSecret.trim();
  try {
    const parsedUri = URI.parse(trimmed);
    if (parsedUri && parsedUri.secret) {
      return parsedUri.secret.base32.replace(/\s+/g, "").toUpperCase();
    }
  } catch (e2) {
    logger.vault.debug(
      "Raw secret is not OTPAuth URI format, falling back to raw secret string:",
      e2
    );
  }
  return trimmed.replace(/\s+/g, "").toUpperCase();
}
async function safeDecodeQr(imageSource) {
  try {
    const res = await r(imageSource);
    return ok(res);
  } catch (e2) {
    console.error("QR Code decoding error:", e2);
    return err2("edit_qr_error_fail");
  }
}
function generateTotpSafe(rawSecret, timeOffset = 0) {
  const secret = parseTotpSecret(rawSecret);
  try {
    const totp = new TOTP({
      secret: Secret.fromBase32(secret)
    });
    const code = totp.generate({
      timestamp: Date.now() + timeOffset
    });
    return ok(code);
  } catch (e2) {
    console.error("TOTP Generation error:", e2);
    return err2("totp_error_invalid_secret");
  }
}

